const rawInput = $input.item.json || {};
const payload = rawInput.body && typeof rawInput.body === 'object' ? rawInput.body : rawInput;

if (payload.error && !payload.events && !payload.stream) {
  return [];
}

const events = Array.isArray(payload.events) ? payload.events : [payload];
const defaultTenantId = String(payload.tenantId || $env.DEFAULT_TENANT_ID || 'eds-360');
const defaultTenantName = String(payload.tenantName || 'EDS-360 / Emerging Defense Solutions');

const streamMap = {
  operations:   { scope: 'department', key: 'operations',          role: 'department_lead', department: 'operations', label: 'Operations & HITL' },
  ops:          { scope: 'department', key: 'operations',          role: 'department_lead', department: 'operations', label: 'Operations & HITL' },
  marketing:    { scope: 'department', key: 'marketing',           role: 'department_lead', department: 'marketing',  label: 'Marketing & Growth' },
  training:     { scope: 'department', key: 'hr',                  role: 'department_lead', department: 'hr',         label: 'Workforce & Training' },
  hr:           { scope: 'department', key: 'hr',                  role: 'department_lead', department: 'hr',         label: 'Workforce & Training' },
  compliance:   { scope: 'it',         key: 'compliance_analysts', role: 'cyber_soc_lead',  department: 'cyber_soc',  label: 'Compliance & Audit' }
};

const out = [];
for (const ev of events) {
  if (!ev || typeof ev !== 'object') continue;
  const rawStream = String(ev.stream || ev.domain || ev.category || 'operations').trim().toLowerCase();
  const cfg = streamMap[rawStream] || streamMap.operations;
  const tenantId = String(ev.tenantId || defaultTenantId);
  const tenantName = String(ev.tenantName || defaultTenantName);
  const ref = String(ev.ref || `SMB-${rawStream.toUpperCase()}-01`);
  const owner = String(ev.owner || `${cfg.label} Lead`);
  const detail = String(ev.detail || ev.summary || `${cfg.label} event ingested via n8n`);
  const status = String(ev.status || 'compliant');

  const kpis = Array.isArray(ev.kpis) && ev.kpis.length > 0 ? ev.kpis : [
    { label: `${cfg.label} Stream`, value: 'Active', sub: `Tenant ${tenantId}`, accent: 'text-emerald-300' },
    { label: 'Last Event Ref', value: ref, sub: owner, accent: 'text-cyan-300' },
    { label: 'Posture Status', value: status, sub: 'n8n normalized sync', accent: status === 'compliant' ? 'text-emerald-300' : 'text-amber-300' },
    { label: 'Audit Attestation', value: 'SHA-256', sub: 'CMMC L2 / CDM ready', accent: 'text-indigo-300' }
  ];

  const items = Array.isArray(ev.items) && ev.items.length > 0 ? ev.items : [
    { ref, owner, detail, status }
  ];

  out.push({
    json: {
      hubPayload: {
        tenantId,
        tenantName,
        scope: ev.scope || cfg.scope,
        key: ev.key || cfg.key,
        sourceLabel: String(ev.sourceLabel || `n8n-smb-${rawStream}`),
        kpis,
        items
      },
      rbacHeaders: {
        role: String(ev.role || cfg.role),
        department: String(ev.department || cfg.department)
      }
    }
  });
}

return out;
